#!/usr/bin/env python3
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
SITE=ROOT/'site'
BASE='/dc-public-realm'

home=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Diplomatic Gifts in Washington</title><link rel="stylesheet" href="{BASE}/assets/style.css"><style>.hero{{max-width:800px;margin:2rem 0}}.hero h1{{margin-bottom:.7rem}}.project{{border-left:4px solid #5a3d16;background:#fffdf8;padding:1rem 1.2rem;margin:2rem 0}}.project h2{{margin-top:.2rem}}.actions{{margin:1.2rem 0}}.actions .button{{margin-bottom:.5rem}}</style></head><body><header><div class="kicker">Diplomatic Gifts in Washington · public art research</div><nav><a href="{BASE}/">Explore</a><a href="{BASE}/collaborate/">Research missions</a><a href="{BASE}/methodology/">About the research</a><a href="{BASE}/data/assertions.json">Data</a></nav></header><main><section class="hero"><div class="kicker">PUBLIC ART · DIPLOMATIC HISTORY</div><h1>Diplomatic Gifts in Washington</h1><p class="lede">This project documents diplomatic monuments in Washington, D.C., and invites the public to help research their histories.</p><p>Government files, newspapers, photographs, archival collections, and museum records can clarify who made these works, how they came to Washington, and how their histories have been recorded.</p></section><section class="project"><div class="kicker">CURRENT PROJECT · URUGUAY</div><h2>José Gervasio Artigas Memorial</h2><p>U.S. and Uruguayan records document the memorial's presentation and connect the Washington bronze to an earlier Artigas monument in Uruguay. Published records differ on the predecessor monument and parts of the fabrication history.</p><div class="actions"><a class="button" href="{BASE}/objects/jose-gervasio-artigas/">Explore the Artigas record</a><a class="button" href="{BASE}/collaborate/artigas/">Join an Artigas research mission</a></div></section><section><h2>Take part in the research</h2><p>You do not need to be an art historian to contribute. Research missions identify a specific question, records that may answer it, and the information needed to document a finding.</p><p>A contribution may confirm an existing statement, qualify it, identify a conflicting account, or leave the question unresolved. Sources are reviewed before the public record changes.</p><p><a class="button" href="{BASE}/collaborate/">Browse research missions</a></p></section><section><h2>Explore the records</h2><div class="grid"><article class="card"><div class="kicker">URUGUAY</div><h3><a href="{BASE}/objects/jose-gervasio-artigas/">José Gervasio Artigas Memorial</a></h3><p>Current research examines the monument's predecessor, fabrication, attribution, and source history.</p></article><article class="card"><div class="kicker">ARGENTINA</div><h3><a href="{BASE}/objects/jose-de-san-martin/">José de San Martín</a></h3><p>Washington monument to José de San Martín. Current research includes attribution and object history.</p></article><article class="card"><div class="kicker">CUBA</div><h3><a href="{BASE}/objects/cuban-american-friendship-urn/">Cuban-American Friendship Urn</a></h3><p>Research record for the urn's object history and diplomatic context.</p></article></div></section><section><h2>How the research works</h2><p>Object pages present the current catalog record. Each historical or attribution statement is linked to its sources. When reliable records disagree, the disagreement remains visible.</p><p>The <a href="{BASE}/methodology/">research methodology</a> explains how sources are reviewed and how records are updated.</p></section></main><footer>Research is ongoing. Records may change when additional sources are reviewed.</footer></body></html>'''

collab=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Artigas Research Missions</title><link rel="stylesheet" href="{BASE}/assets/style.css"><style>.mission{{border-left:4px solid #7a3e00;background:#fffdf8;padding:1rem 1.2rem;margin:1.2rem 0}}.mission h3{{margin-top:.2rem}}.small{{font-family:ui-sans-serif,system-ui,sans-serif;color:#666;font-size:.9rem}}.steps{{counter-reset:step;list-style:none;padding:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:1rem}}.steps li{{border-top:3px solid #ddd;padding-top:.6rem}}.steps li:before{{counter-increment:step;content:counter(step);font-family:ui-sans-serif,system-ui,sans-serif;font-weight:700;margin-right:.5rem}}</style></head><body><header><div class="kicker">Diplomatic Gifts in Washington · public research</div><nav><a href="{BASE}/">Explore</a><a href="{BASE}/collaborate/">Research missions</a><a href="{BASE}/objects/jose-gervasio-artigas/">Artigas record</a><a href="{BASE}/methodology/">About the research</a></nav></header><main><div class="kicker">JOSÉ GERVASIO ARTIGAS MEMORIAL</div><h1>Help Research the Artigas Memorial</h1><p class="lede">Historical records leave several questions about the Washington monument unresolved. You can help locate the records needed to answer them.</p><p>Choose a mission below. Each mission defines the question and the material being sought. No specialized training is required; accurate citations and complete records are more useful than interpretation.</p><h2>Research missions</h2><article class="mission"><div class="kicker">MISSION 1 · NEWSPAPER RESEARCH</div><h3>Find the 1949 <em>El Día</em> account</h3><p>Locate the complete article “Monumento a Artigas en Washington.” It may contain contemporary information about production, financing, shipment, or installation.</p><p><strong>Useful contribution:</strong> complete article pages, continuation pages, captions, credits, publication date, and page numbers.</p><a class="button" href="{BASE}/tasks/ury-art-002/">Mission details</a></article><article class="mission"><div class="kicker">MISSION 2 · ARCHIVAL RESEARCH</div><h3>Find the original commission records</h3><p>Uruguay's heritage documentation refers to an 1894 commission and an 1896 contract concerning Juan Luis Blanes, Juan Manuel Blanes, and Dante Costa. Locate the underlying records.</p><p><strong>Useful contribution:</strong> archival citation, catalog record, image, transcription, or authoritative reproduction.</p><a class="button" href="{BASE}/tasks/ury-art-003/">Mission details</a></article><article class="mission"><div class="kicker">MISSION 3 · DIPLOMATIC HISTORY</div><h3>Trace the Washington monument, 1947–1951</h3><p>Locate correspondence or administrative records concerning authorization, fabrication, shipment, dedication, or installation of the Washington bronze.</p><p><strong>Useful contribution:</strong> folder citation, scan, finding-aid reference, or repository contact that identifies relevant records.</p><a class="button" href="{BASE}/tasks/ury-art-001/">Mission details</a></article><article class="mission"><div class="kicker">MISSION 4 · MUSEUM RECORDS</div><h3>Trace the Smithsonian inventory's sources</h3><p>The Smithsonian inventory cites earlier research without assigning each source to individual statements. Help locate those materials so their contribution to the catalog record can be documented.</p><p><a href="https://github.com/danielastone/dc-public-realm/issues/19">Goode (1974)</a> · <a href="https://github.com/danielastone/dc-public-realm/issues/20">Michael Richman research</a> · <a href="https://github.com/danielastone/dc-public-realm/issues/21">NPS record (1985)</a> · <a href="https://github.com/danielastone/dc-public-realm/issues/22">Smithsonian research project (1991)</a></p></article><h2>What happens to your contribution</h2><ol class="steps"><li><strong>You submit a source.</strong><br><span class="small">Provide enough information for another researcher to locate the same record.</span></li><li><strong>The source is reviewed.</strong><br><span class="small">The project checks identity, date, relevance, and whether the statement derives from another source.</span></li><li><strong>The evidence is recorded.</strong><br><span class="small">Accepted material is linked to the specific historical or attribution statement it bears on.</span></li><li><strong>The public record is updated.</strong><br><span class="small">The source may confirm, qualify, contradict, or leave the statement unresolved.</span></li></ol><h2>Ways to contribute</h2><p>Useful contributions include archival citations, finding-aid references, newspaper pages, photographs of inscriptions, catalog records, scans where reproduction is permitted, translations, and corrections supported by a source.</p><p>If an archive does not permit public posting of a scan, submit the citation and repository information instead.</p><h2>Research standards</h2><p>A contribution does not become part of the catalog record automatically. Sources are reviewed first. When reliable records disagree, both remain documented until additional evidence resolves the difference.</p><p><a class="button" href="{BASE}/objects/jose-gervasio-artigas/">Explore the Artigas record</a><a class="button" href="{BASE}/methodology/">Research methodology</a></p></main><footer>Public contributions support the research record. Submitted material is reviewed before publication.</footer></body></html>'''

(SITE/'index.html').write_text(home,encoding='utf-8')
d=SITE/'collaborate'/'artigas'; d.mkdir(parents=True,exist_ok=True); (d/'index.html').write_text(collab,encoding='utf-8')
print('Updated public research engagement pages')
